version.transform:
(
  $data := $ 
    ~> | $ | {
      "category": $moment(creditedAt).format("MM/DD") & " " & shift.name,
      /* Sort 3-1-2 */    
      "sort": $moment(creditedAt).format("MM/DD") & " " & $replace(shift.name, "3", "0")
    } |;

  $groupedData := ($data{
    category: {
      "category": $first(category),
      "sort": $first(sort),
      "prodHours": $sum(productionTime) / 3600,
      "plannedDowntimeHours": $sum(plannedDowntime) / 3600,
      "unplannedDowntimeHours": $sum(unplannedDowntime) / 3600,
      "otherHours": $sum(other) / 3600
    }
  } ~> $values)^(>sort);

  {
    "categories": [
        {
            "category": [$groupedData.{
              "label": category
            }]
        }
    ],
    "dataSet": [
        {
            "seriesName": "Production",
            "color": "#43a047",
            "data": [$groupedData.{
              "value": prodHours
            }]
        },
        {
            "seriesName": "Planned Down",
            "color": "#ffa000",
            "data": [$groupedData.{
              "value": plannedDowntimeHours
            }]
        },
        {
            "seriesName": "Unplanned Down",
            "color": "#f44336",
            "data": [$groupedData.{
              "value": unplannedDowntimeHours
            }]
        },
        {
            "seriesName": "Other",
            "color": "#1e88e5",
            "data": [$groupedData.{
              "value": otherHours
            }]
        }
    ]
  }
)
